        training = [p for j in range(K) if j != k for p in folds[j]]
        s.append(mse(fit(training), folds[k]))
    return sum(s) / K

print(round(cv(fit_line), 4), round(cv(lambda d: fit_ridge(d, 4, 0.3)[1]), 4), round(cv(lambda d: fit_ridge(d, 4, 0.0)[1]), 4))
